     2	
     3	import type { ConversationComposerInputProps, ConversationComposerRootProps, ConversationComposerDropzoneProps } from "@za38.03/agent-ui-plugins/composer-support";
     4	
     5	import { useContext, type FC, type ReactNode } from "react";
     6	import { ComposerPrimitive, QueueItemPrimitive, AuiIf, XIcon, ComposerHostConfigContext, ComposerInputHostContext, ComposerAttachments, TooltipIconButton,
     7	  useConversationComposerAwaitingReply, useConversationComposerSendGuard, useAgentUILocale } from "@za38.03/agent-ui-plugins/composer-support";
     8	import { ComposerTextareaInput } from "./textarea.js";
     9	
    10	export interface ComposerQueueLabels {
    11	  queued: string;
    12	  removeQueued: string;
    13	}
    14	
    15	export const ComposerQueue: FC<ComposerQueueLabels> = ({ queued, removeQueued }) => (
    16	  <AuiIf condition={(s) => s.thread.capabilities.queue && s.composer.queue.length > 0}>
    17	    <div data-agent-ui-owned="" data-slot="aui_composer-queue" className="border-primary/20 bg-primary/5 flex flex-col gap-1 rounded-lg border p-2">
    18	      <span data-agent-ui-owned="" className="text-muted-foreground text-xs">{queued}</span>
    19	      <ComposerPrimitive.Queue>
    20	        {() => (
    21	          <div data-agent-ui-owned="" data-slot="aui_composer-queue-item" className="flex items-center gap-2 rounded-md bg-background/60 px-2 py-1 text-sm">
    22	            <div data-agent-ui-owned="" className="min-w-0 flex-1 break-words"><QueueItemPrimitive.Text /></div>
    23	            <QueueItemPrimitive.Remove asChild>
    24	              <TooltipIconButton tooltip={removeQueued} aria-label={removeQueued} type="button" className="size-6 shrink-0">
    25	                <XIcon className="size-3.5" />
    26	              </TooltipIconButton>
    27	            </QueueItemPrimitive.Remove>
    28	          </div>
    29	        )}
    30	      </ComposerPrimitive.Queue>
    31	    </div>
    32	  </AuiIf>
    33	);
    34	
    35	export interface CanonicalComposerProps {
    36	  inputProps?: ConversationComposerInputProps;
    37	  rootProps?: ConversationComposerRootProps;
    38	  dropzoneProps?: ConversationComposerDropzoneProps;
    39	  autoFocus?: boolean | undefined;
    40	  placeholder: string;
    41	  inputAriaLabel: string;
    42	  queueLabels: ComposerQueueLabels;
    43	  triggers?: ReactNode;
    44	  beforeInput?: ReactNode;
    45	  input?: ReactNode;
    46	  leadingActions?: ReactNode;
    47	  trailingActions?: ReactNode;
    48	  submitAction?: ReactNode;
    49	}
    50	
    51	export const CanonicalComposer: FC<CanonicalComposerProps> = ({
    52	  inputProps, rootProps, dropzoneProps,
    53	  autoFocus,
    54	  placeholder,
    55	  inputAriaLabel,
    56	  queueLabels,
    57	  triggers,
    58	  beforeInput,
    59	  input,
    60	  leadingActions,
    61	  trailingActions,
    62	  submitAction,
    63	}) => {
    64	  const inheritedHostConfig = useContext(ComposerHostConfigContext);
    65	  const resolvedAutoFocus = autoFocus ?? inheritedHostConfig.autoFocus;
